#define TinyML_TASK_PRIORITY             2         //!< Task priorities
#define TinyML_TASK_STACK_SIZE           512 * 40   //!<  Task stack size

/*============================================================================*
 *                              Variables
 *============================================================================*/
void *TinyML_task_handle;   //!< APP Task handle



/*============================================================================*
 *                              Functions
 *============================================================================*/
void TinyML_main_task(void *p_param);
