/**
 * @brief        App task to handle events & messages
 * @param[in]    p_param    Parameters sending to the task
 * @return       void
 */
void TinyML_main_task(void *p_param)
{
    // uint32_t actual_mhz = 0;
    // pm_cpu_freq_set(125, &actual_mhz);
    // DBG_DIRECT("CPU actual clock is %d MHz", actual_mhz);

    dwt_cyccnt_init();

    DBG_DIRECT("TinyML_main_task start 01");


    // image classification demo (0~9)
    {
        float *features = ts_malloc(sizeof(float) * IC_IMAGE_FEATURES);

        if (features == NULL)
        {
            DBG_DIRECT("[TS] failed: out of memory\n");
            return;
        }

        int ret = ic_normalize_rgb888_interleaved(
                      raw_image,
                      IC_IMAGE_DATA_SIZE,
                      features,
                      IC_IMAGE_FEATURES
                  );

        if (ret == IC_SUCCESS)
        {
            int infer_ret = ts_run_inference(features, IC_FEATURE_SIZE);

            DBG_DIRECT("[TS] tflite model infer success, ret = %d\n", infer_ret);
        }
        else
        {
            DBG_DIRECT("[TS] tflite model infer failed: %d\n", ret);
        }

        ts_free(features);
    }




    while (true)
    {

    }
}
